package com.arcvision.arcledger.data.dao; import android.content.*; import android.database.Cursor; import com.arcvision.arcledger.data.db.DatabaseHelper; import com.arcvision.arcledger.data.model.Customer; import java.util.*; public class CustomerDao {private final DatabaseHelper h; public CustomerDao(Context c){h=new DatabaseHelper(c);} public List<Customer> getAllCustomers(){Cursor c=h.getReadableDatabase().rawQuery("SELECT * FROM customers",null);List<Customer> l=new ArrayList<>();while(c.moveToNext()){Customer x=new Customer();x.id=c.getLong(0);x.fullName=c.getString(1);x.phone=c.getString(2);l.add(x);}c.close();return l;}}
